// Base case: Terminates recursion
void process_pack() {}

// Recursive step: Handles head (T) and unpacks tail (Args...)
template<typename T, typename... Args>
void process_pack(const T& head, const Args&... tail) {
    // Action on 'head' argument
    // e.g., print(head);

    // Unpack the rest and recurse
    process_pack(tail...);
}

// Alternative C++17 folding expression (often preferred)
template<typename... Args>
auto sum_values(Args... args) {
    return (args + ... + 0); // Binary left fold
}
